        response.setContentType("text/html");
        response.getWriter().write("<html><body>");
        response.getWriter().write(output);
        response.getWriter().write("</body></html>");
    }

    private String escapeHtml(String input) {
        if (input == null) {
            return "";
        }
        return input
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;");
    }
}

