        out.println("<html><body>");
        out.println("<h1>" + output + "</h1>");
        out.println("</body></html>");
    }

    private String encodeForHtml(String input) {
        if (input == null) {
            return "";
        }
        return input.replaceAll("&", "&amp;")
                    .replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")
                    .replaceAll("\"", "&quot;")
                    .replaceAll("'", "&#39;");
    }
}

