import java.io.IOException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

import org.owasp.encoder.Encode;

public class UserInputHandler {

    public void handleUserInput(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("input");

        // Properly sanitize user input by escaping special characters
        String sanitizedUserInput = Encode.forHtml(userInput);

        // Write sanitized user input in the response
        response.getWriter().write("<p>User Input: " + sanitizedUserInput + "</p>");
    }
}

