        int index;
        int size = specificKeyMembers.size();
        for(index = 0;
            (index < size) && !match;
            index++)
        {
          keyMember = specificKeyMembers.get(index);
          // Drop out if one of the members matches it
          if(keyMember.filterMatches(item))
          {
            match = true;
            matchingMember = keyMember;
          }
        }
