import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class XSSFixedServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        PrintWriter out = response.getWriter();

        out.println("<html>");
        out.println("<body>");
        out.println("<h1>User Input: " + sanitizeInput(userInput) + "</h1>");
        out.println("</body>");
        out.println("</html>");
    }

    private String sanitizeInput(String input) {
        // Replace special characters with their HTML entities to prevent XSS
        return input != null ? input.replaceAll("<", "&lt;").replaceAll(">", "&gt;") : "";
    }
}

