        String output = "Hello, " + safeUserInput + "!";

        response.setContentType("text/html");
        response.getWriter().write("<html><body><h1>" + output + "</h1></body></html>");
    }

    private String escapeHtml(String input) {
        return input == null ? "" : input
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;");
    }
}

