import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class XSSProtectedServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        response.setContentType("text/html");
        PrintWriter out = response.getWriter();

        String userInput = request.getParameter("input");

        out.println("<html>");
        out.println("<head><title>XSS Protected Page</title></head>");
        out.println("<body>");
        out.println("<h1>Hello, " + encodeHtml(userInput) + "</h1>"); // Encode user input
        out.println("</body>");
        out.println("</html>");
    }

    private String encodeHtml(String input) {
        if (input == null) {
            return "";
        }

        return input
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace("\"", "&quot;")
            .replace("'", "&#39;");
    }
}

