import java.util.Scanner;

public class SecureBufferExample {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Limiting the buffer size to prevent buffer overflow
        int bufferSize = Math.min(userInput.length(), 10);
        char[] buffer = new char[bufferSize];

        // Copying user input into the fixed size buffer with proper bounds checking
        userInput.getChars(0, bufferSize, buffer, 0);

        System.out.println("User input copied into buffer successfully");
    }
