import java.io.*;

public class CommandInjectionExample {
    public static void main(String[] args) throws IOException, InterruptedException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        System.out.print("Enter a command to execute: ");
        String userInput = br.readLine();

        // Secure code: using ProcessBuilder to execute commands
        ProcessBuilder processBuilder = new ProcessBuilder();
        processBuilder.command("bash", "-c", userInput);

        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;

        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }

        int exitCode = process.waitFor();

        if (exitCode == 0) {
            System.out.println("Command executed successfully.");
        } else {
            System.out.println("Command execution failed with exit code: " + exitCode);
        }
    }
}

