public class SecureBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        char[] buffer = new char[10]; // Buffer size is limited to 10 characters

        // Copy user input into the buffer with bounds checking
        int lengthToCopy = Math.min(name.length(), buffer.length); // Limit copy length to buffer size
        name.getChars(0, lengthToCopy, buffer, 0);

        System.out.println("Hello, " + new String(buffer)); // No Buffer Overflow risk
    }
}

