import java.util.Scanner;
import java.util.Arrays;

public class SecureBuffer {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        char[] buffer = new char[10];

        // Safely copy user input into a fixed-size buffer
        int length = Math.min(userInput.length(), buffer.length);
        userInput.getChars(0, length, buffer, 0);

        // Fill the remaining space in the buffer with zeros
        if (length < buffer.length) {
            Arrays.fill(buffer, length, buffer.length, '\0');
        }

        System.out.println("Buffer content: " + new String(buffer));
    }
}

