import java.util.Scanner;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Limit the input size to avoid buffer overflow
        if (name.length() > 10) {
            System.out.println("Input exceeds maximum allowed length.");
            return;
        }

        char[] buffer = new char[10];

        // Copy input safely into the buffer
        System.arraycopy(name.toCharArray(), 0, buffer, 0, Math.min(name.length(), buffer.length));

        System.out.println("Hello, " + String.valueOf(buffer));
    }
}

