private static void mergeReversed(List<String> merged,
	                                  final List<String> other) {

		if(other.isEmpty())
			return;

		if(merged.isEmpty()) {
			merged.addAll(other);
			return;
		}

		ListIterator<String> m = merged.listIterator();
		ListIterator<String> o = other.listIterator();

		String nextM, prevO;
		prevO = o.next();
		while(m.hasNext()) {
			// peek at m
			nextM = m.next();
			m.previous();

			//insert from O until exhausted or occurs after nextM
			while(prevO.compareTo(nextM) > 0) {
				m.add(prevO);
				if(!o.hasNext()) {
					return;
				}
				prevO = o.next();
			}
			//remove duplicates
			if(prevO.equals(nextM)) {
				if(!o.hasNext()) {
					return;
				}
				prevO = o.next();
			}

			m.next();
		}
		m.add(prevO);
		while(o.hasNext()) {
			m.add(o.next());
		}

	}

