public class SecureBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine().trim(); // Read a full line of input and trim any leading or trailing whitespace

        int bufferSize = 10;
        char[] buffer = new char[bufferSize];

        // Copy characters from userInput to buffer, ensuring it fits within the buffer size
        int length = Math.min(userInput.length(), bufferSize);
        userInput.getChars(0, length, buffer, 0);

        System.out.println("Buffer contents: " + new String(buffer));
