    private String sanitizeInput(String input) {
        // Replace potentially dangerous characters with their HTML entity equivalents
        return input != null ? input.replace("&", "&amp;")
                                   .replace("<", "&lt;")
                                   .replace(">", "&gt;")
                                   .replace("\"", "&quot;")
                                   .replace("'", "&#39;") : "";
    }
}

