import java.util.Scanner;

public class SecureBuffer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        // Limiting buffer size to prevent buffer overflow
        int bufferSize = 10;
        char[] buffer = new char[bufferSize];

        // Copy user input into the buffer with proper length validation
        int length = Math.min(input.length(), bufferSize);
        for (int i = 0; i < length; i++) {
            buffer[i] = input.charAt(i);
        }

        System.out.println("Input successfully stored in buffer: " + new String(buffer));
    }
}

