        boolean isName = false;

        if (is(TokenType.STAR, true)) {

            if (is(TokenType.COLON, true)) {
                isName = true; // < "*" ":" NCName > .
            } else {

                return mIsAtt // "*"
                    ? new AttributeFilter(getTransaction()) : new ElementFilter(getTransaction());

            }
        }

        filter = new WildcardFilter(getTransaction(), parseNCName(), isName);
