import java.util.Scanner;

public class SafeBufferCopyExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String input = scanner.nextLine().trim(); // Use nextLine() to read the whole line

        char[] buffer = new char[10];

        // Copy input into buffer safely
        int length = Math.min(input.length(), buffer.length);
        input.getChars(0, length, buffer, 0);

        System.out.println("Welcome, " + new String(buffer));
    }
}

