import java.io.IOException;
import java.io.InputStreamReader;

public class SecureCommandExecution {
    public static void main(String[] args) {
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            System.out.print("Enter a command to execute: ");
            String userInput = reader.readLine();

            // Sanitize user input to prevent command injection
            String sanitizedInput = userInput.replaceAll("[^a-zA-Z0-9]", "");

            // Execute the sanitized command using ProcessBuilder
            Process process = new ProcessBuilder(sanitizedInput).start();

            BufferedReader inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = inputReader.readLine()) != null) {
                System.out.println(line);
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

