public class SecureServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        PrintWriter out = response.getWriter();

        // Properly encode user input to prevent XSS
        String encodedUserInput = encodeForHtml(userInput);

        out.println("<p>User input: " + encodedUserInput + "</p>");
    }

    private String encodeForHtml(String userInput) {
        if (userInput == null) {
            return "";
        }

        // Replace special characters with their HTML entity equivalents
        userInput = userInput.replace("&", "&amp;")
                             .replace("<", "&lt;")
                             .replace(">", "&gt;")
                             .replace("\"", "&quot;")
                             .replace("'", "&#x27;")
                             .replace("/", "&#x2F;");

        return userInput;
    }
}

