        String output = "<html><body>Welcome " + safeUserInput + "</body></html>";
        response.getWriter().write(output);
    }

    private String encodeForHTML(String input) {
        if (input == null) {
            return "";
        }
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#39;");
    }
}

