        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Validate input length to prevent buffer overflow
        if (name.length() > 10) {
            System.out.println("Input exceeds maximum allowed length.");
            return;
        }

        // Safely copy user input into a fixed-size buffer with proper bounds checking
        char[] buffer = new char[10];
        name.getChars(0, Math.min(name.length(), 10), buffer, 0);

