public class XSSSecureServlet extends HttpServlet {

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("input");
        String encodedUserInput = encodeForHTML(userInput); // Properly encoding user input

        String output = "<p>" + encodedUserInput + "</p>";

        response.getWriter().write(output);
    }

    private String encodeForHTML(String input) {
        Codec codec = ESAPI.encoder();
        return codec.encodeForHTML(input);
    }
}

